/**
 * Font loaders for every font in SUPPORTED_FONTS (src/config/presets.ts).
 * next/font needs static calls, so each supported font is declared here once.
 * preload is off because only the two fonts in use are ever downloaded; the
 * browser fetches a font file only when the page actually uses it.
 * Generated by `npm run fonts:all`; `npm run fonts:pin` loads only this
 * site's fonts (done by /aksumite-template).
 */

import {
  DM_Sans,
  Fraunces,
  Inter,
  Lora,
  Manrope,
  Montserrat,
  Noto_Sans_Ethiopic,
  Playfair_Display,
  Plus_Jakarta_Sans,
  Poppins,
  Space_Grotesk,
} from 'next/font/google';
import type { FontName } from '@/config/presets';

const inter = Inter({ subsets: ['latin'], display: 'swap', preload: false });
const dmSans = DM_Sans({ subsets: ['latin'], display: 'swap', preload: false });
const manrope = Manrope({ subsets: ['latin'], display: 'swap', preload: false });
const plusJakartaSans = Plus_Jakarta_Sans({ subsets: ['latin'], display: 'swap', preload: false });
const spaceGrotesk = Space_Grotesk({ subsets: ['latin'], display: 'swap', preload: false });
const montserrat = Montserrat({ subsets: ['latin'], display: 'swap', preload: false });
const poppins = Poppins({
  weight: ['400', '500', '600', '700'],
  subsets: ['latin'],
  display: 'swap',
  preload: false,
});
const playfairDisplay = Playfair_Display({ subsets: ['latin'], display: 'swap', preload: false });
const fraunces = Fraunces({ subsets: ['latin'], display: 'swap', preload: false });
const lora = Lora({ subsets: ['latin'], display: 'swap', preload: false });

// Amharic letters. The browser downloads this file only for a page that has them.
const notoSansEthiopic = Noto_Sans_Ethiopic({
  subsets: ['ethiopic'],
  display: 'swap',
  preload: false,
});
export const ETHIOPIC_FONT = notoSansEthiopic.style.fontFamily;

export const FONT_FAMILIES: Record<FontName, string> = {
  Inter: inter.style.fontFamily,
  'DM Sans': dmSans.style.fontFamily,
  Manrope: manrope.style.fontFamily,
  'Plus Jakarta Sans': plusJakartaSans.style.fontFamily,
  'Space Grotesk': spaceGrotesk.style.fontFamily,
  Montserrat: montserrat.style.fontFamily,
  Poppins: poppins.style.fontFamily,
  'Playfair Display': playfairDisplay.style.fontFamily,
  Fraunces: fraunces.style.fontFamily,
  Lora: lora.style.fontFamily,
};
